\section*{Assumptions}
\begin{assumption}[Smoothness]\label{as:smooth}
The stochastic loss $f(\cdot;z)$ is $L$‑smooth for every $z$, i.e.
\[
\|\nabla f(w;z)-\nabla f(w';z)\|\le L\|w-w'\|\quad\forall w,w'\in\R^{d}.
\]
Consequently, the expected objective $F(w)=\E_z[f(w;z)]$ is also $L$‑smooth.
\end{assumption}
\begin{assumption}[Bounded Stochastic Gradients]\label{as:bound}
There exists $G>0$ such that $\|g_t\|\le G$ almost surely for all $t$.
\end{assumption}
\begin{assumption}[Unbiasedness and Bounded Variance]\label{as:unbiased}
\[
\E[g_t\mid\mathcal{F}_{t-1}]=\nabla F(w_t),\qquad
\E\bigl[\|g_t-\nabla F(w_t)\|^2\mid\mathcal{F}_{t-1}\bigr]\le\sigma^2,
\]
where $\mathcal{F}_{t-1}$ is the $\sigma$‑algebra generated by $\{w_1,\dots,w_t\}$.
\end{assumption}
\begin{assumption}[Hyper‑parameter Regime]\label{as:hyper}
The decay rates satisfy $0\le\beta_1<\sqrt{\beta_2}<1$ and the stepsize $\eta$ obeys
\[
\eta \le \frac{(1-\beta_1)\sqrt{1-\beta_2}}{L\,(1+\sqrt{\beta_2})}.
\]
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}[Non‑convex Convergence of AMSGrad]\label{thm:main}
Under Assumptions \ref{as:smooth}–\ref{as:hyper}, let $\{w_t\}_{t=1}^{T}$ be the iterates generated by AMSGrad with step size $\eta$. Define the averaged gradient norm
\[
\overline{G}_T \;:=\; \frac{1}{T}\sum_{t=1}^{T}\E\bigl[\|\nabla F(w_t)\|^2\bigr].
\]
Then
\[
\boxed{\;
\overline{G}_T \;\le\;
\frac{2L\bigl(F(w_1)-F^\star\bigr)}{(1-\beta_1)\eta T}
\;+\;
\frac{2\eta\,G^2\,(1+\log T)}{(1-\beta_1)(1-\beta_2)}\;
}
\tag{6}
\]
where $F^\star=\inf_{w}F(w)$. Consequently,
\[
\overline{G}_T = O\!\left(\frac{\log T}{\sqrt{T}}\right)
\quad\text{if}\quad
\eta = \Theta\!\bigl(T^{-1/2}\bigr).
\]
\end{theorem}

\section*{Theoretical Properties}
\begin{itemize}[leftmargin=*]
\item \textbf{Stability.} The monotone max operator $\tilde v_t$ guarantees that the denominator in (5) never decreases, preventing the uncontrolled growth of the effective stepsize that can cause divergence in Adam.
\item \textbf{Hyper‑parameter Sensitivity.} The bound (6) exhibits linear dependence on $\eta$ and inverse dependence on $(1-\beta_1)$. Choosing $\beta_1$ close to $1$ slows down convergence but reduces variance; $\beta_2$ appears only inside $(1-\beta_2)^{-1}$, reflecting the role of the second‑moment decay.
\item \textbf{Comparison to Adam.} For Adam the analogous bound contains an extra term proportional to $\sum_{t=1}^{T}\|\sqrt{v_t}\|^{-1}$ which can be unbounded. The max‑operator eliminates this term, yielding the clean $O(\log T/\sqrt{T})$ rate.
\item \textbf{Special Cases.}
    \begin{enumerate}
    \item If $F$ is convex, the same proof yields $\mathcal{O}(\log T/T)$ convergence of the optimality gap.
    \item When $L=0$ (i.e., linear functions) the first term in (6) vanishes and the bound reduces to the pure variance term.
    \end{enumerate}
\end{itemize}

\section*{Discussion}
The theorem shows that AMSGrad attains the same order of convergence as (deterministic) gradient descent on smooth non‑convex objectives, up to a logarithmic factor caused by the adaptive learning rates. The monotonicity of $\tilde v_t$ is the key technical device that allows us to bound the accumulated “effective stepsizes’’ and avoid the pathological examples where Adam fails.

