\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Smoothness Inequality]\label{lem:smooth}
If $F$ is $L$‑smooth then for any $w,w'$
\[
F(w')\le F(w) + \ip{\nabla F(w)}{w'-w} + \frac{L}{2}\|w'-w\|^2 .
\]
\end{lemma}
\begin{proof}
Standard consequence of $L$‑smoothness; see e.g. Nesterov (2004). \hfill\qedhere
\end{proof}

\begin{lemma}[Bound on Bias‑Corrected First Moment]\label{lem:m_bound}
For all $t$,
\[
\|\hat m_t\| \le \frac{(1-\beta_1^{\,t})}{1-\beta_1}\,G \le \frac{G}{1-\beta_1}.
\]
\end{lemma}
\begin{proof}
From (1),
\[
m_t = (1-\beta_1)\sum_{i=1}^{t}\beta_1^{\,t-i} g_i .
\]
Taking norms, using $\|g_i\|\le G$, and dividing by $1-\beta_1^{\,t}$ yields the claim. \hfill\qedhere
\end{proof}

\begin{lemma}[Monotonicity of $\tilde v_t$]\label{lem:max}
By definition (4), $\tilde v_t \succeq \tilde v_{t-1}$ element‑wise for all $t$.
\end{lemma}
\begin{proof}
Immediate from the element‑wise maximum operation. \hfill\qedhere
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:main}. Throughout we condition on $\mathcal{F}_{t-1}$.

\noindent\textbf{[Step 1]} Apply Lemma \ref{lem:smooth} with $w'=w_{t+1}$ and $w=w_t$:
\begin{equation}
F(w_{t+1})\le F(w_t) + \ip{\nabla F(w_t)}{w_{t+1}-w_t}
+ \frac{L}{2}\norm{w_{t+1}-w_t}^2 . \tag{7}
\end{equation}

\noindent\textbf{[Step 2]} Substitute the update (5):
\[
w_{t+1}-w_t = -\eta\,\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}.
\]
Hence
\[
\ip{\nabla F(w_t)}{w_{t+1}-w_t}
= -\eta\;\ip{\nabla F(w_t)}{\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}} . \tag{8}
\]

\noindent\textbf{[Step 3]} Expand the squared norm term:
\[
\norm{w_{t+1}-w_t}^2
= \eta^2 \norm{\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}}^2 . \tag{9}
\]

\noindent\textbf{[Step 4]} Insert (8) and (9) into (7):
\[
F(w_{t+1})\le F(w_t)
- \eta\;\ip{\nabla F(w_t)}{\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}}
+ \frac{L\eta^2}{2}\norm{\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}}^2 . \tag{10}
\]

\noindent\textbf{[Step 5]} Take conditional expectation $\E[\cdot\mid\mathcal{F}_{t-1}]$.
Using unbiasedness (Assumption \ref{as:unbiased}) we replace $\nabla F(w_t)$ by $\E[g_t\mid\mathcal{F}_{t-1}]$:
\[
\E\!\bigl[F(w_{t+1})\mid\mathcal{F}_{t-1}\bigr]
\le F(w_t)
- \eta\;\E\!\Bigl[\ip{g_t}{\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}}\mid\mathcal{F}_{t-1}\Bigr]
+ \frac{L\eta^2}{2}\E\!\Bigl[\norm{\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}}^2\mid\mathcal{F}_{t-1}\Bigr]. \tag{11}
\]

\noindent\textbf{[Step 6]} Relate $g_t$ to $\hat m_t$. From (1) and (3),
\[
\hat m_t = \frac{(1-\beta_1)}{1-\beta_1^{\,t}}\,\sum_{i=1}^{t}\beta_1^{\,t-i} g_i .
\]
Thus
\[
\E\!\bigl[g_t^{\top}\hat m_t\mid\mathcal{F}_{t-1}\bigr]
= \frac{1-\beta_1}{1-\beta_1^{\,t}}\,\E\!\bigl[g_t^{\top}g_t\mid\mathcal{F}_{t-1}\bigr]
+ \frac{1-\beta_1}{1-\beta_1^{\,t}}\,\sum_{i=1}^{t-1}\beta_1^{\,t-i}\E\!\bigl[g_t^{\top}g_i\mid\mathcal{F}_{t-1}\bigr].
\]
Since $g_i$ for $i<t$ is $\mathcal{F}_{t-1}$‑measurable and $\E[g_t\mid\mathcal{F}_{t-1}]=\nabla F(w_t)$,
\[
\E\!\bigl[g_t^{\top}g_i\mid\mathcal{F}_{t-1}\bigr]=\nabla F(w_t)^{\top}g_i .
\]
Hence
\[
\E\!\bigl[g_t^{\top}\hat m_t\mid\mathcal{F}_{t-1}\bigr]
\ge \frac{1-\beta_1}{1-\beta_1^{\,t}}\|\nabla F(w_t)\|^2 . \tag{12}
\]
(The inequality follows from dropping the non‑negative cross terms $\|g_i\|^2$ and using $\|g_t\|\le G$.)

\noindent\textbf{[Step 7]} Lower bound the inner product in (11) using (12) and the element‑wise monotonicity of $\tilde v_t$ (Lemma \ref{lem:max}). Since each coordinate of $\tilde v_t$ is at least as large as the corresponding coordinate of $\hat v_t$, we have
\[
\frac{1}{\sqrt{\tilde v_t}+\epsilon}
\ge \frac{1}{\sqrt{\hat v_t}+\epsilon}.
\]
Therefore,
\[
\E\!\Bigl[\ip{g_t}{\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}}\mid\mathcal{F}_{t-1}\Bigr]
\ge \frac{1}{\sqrt{\hat v_{t,\max}}+\epsilon}\,\E\!\bigl[g_t^{\top}\hat m_t\mid\mathcal{F}_{t-1}\bigr], \tag{13}
\]
where $\hat v_{t,\max}$ denotes the largest coordinate of $\hat v_t$. Using the bound $\hat v_{t,\max}\le G^2/(1-\beta_2)$ (derived from (2) and Lemma \ref{lem:m_bound}) we obtain a constant $C_v:=\sqrt{G^2/(1-\beta_2)}+\epsilon$ such that
\[
\frac{1}{\sqrt{\tilde v_t}+\epsilon}\ge \frac{1}{C_v}. \tag{14}
\]

\noindent\textbf{[Step 8]} Combine (12)–(14) to obtain
\[
\E\!\Bigl[\ip{g_t}{\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}}\mid\mathcal{F}_{t-1}\Bigr]
\ge \frac{1-\beta_1}{(1-\beta_1^{\,t})\,C_v}\,\|\nabla F(w_t)\|^2 . \tag{15}
\]

\noindent\textbf{[Step 9]} Upper bound the squared norm term in (11). By Lemma \ref{lem:m_bound},
\[
\|\hat m_t\|\le \frac{G}{1-\beta_1}.
\]
Moreover $\tilde v_t\succeq \hat v_t\ge 0$, thus
\[
\norm{\frac{\hat m_t}{\sqrt{\tilde v_t}+\epsilon}}^2
\le \frac{\|\hat m_t\|^2}{\epsilon^2}
\le \frac{G^2}{(1-\beta_1)^2\epsilon^2}. \tag{16}
\]

\noindent\textbf{[Step 10]} Insert bounds (15) and (16) into (11):
\[
\E\!\bigl[F(w_{t+1})\mid\mathcal{F}_{t-1}\bigr]
\le F(w_t)
- \frac{\eta(1-\beta_1)}{(1-\beta_1^{\,t})C_v}\,\|\nabla F(w_t)\|^2
+ \frac{L\eta^2 G^2}{2(1-\beta_1)^2\epsilon^2}. \tag{17}
\]

\noindent\textbf{[Step 11]} Take total expectation and sum from $t=1$ to $T$:
\[
\sum_{t=1}^{T}\frac{\eta(1-\beta_1)}{(1-\beta_1^{\,t})C_v}
\E\bigl[\|\nabla F(w_t)\|^2\bigr]
\le F(w_1)-\E[F(w_{T+1})]
+ \frac{L\eta^2 G^2 T}{2(1-\beta_1)^2\epsilon^2}. \tag{18}
\]

\noindent\textbf{[Step 12]} Since $F(w_{T+1})\ge F^\star$, we replace it by $F^\star$ and bound the harmonic‑type coefficient:
\[
\frac{1}{(1-\beta_1^{\,t})}\le \frac{1}{1-\beta_1}\quad\forall t,
\]
hence
\[
\frac{\eta(1-\beta_1)}{(1-\beta_1^{\,t})C_v}\ge
\frac{\eta(1-\beta_1)^2}{C_v}. \tag{19}
\]
Thus (18) yields
\[
\frac{\eta(1-\beta_1)^2}{C_v}\sum_{t=1}^{T}\E\bigl[\|\nabla F(w_t)\|^2\bigr]
\le F(w_1)-F^\star
+ \frac{L\eta^2 G^2 T}{2(1-\beta_1)^2\epsilon^2}. \tag{20}
\]

\noindent\textbf{[Step 13]} Divide by $T$ and rearrange:
\[
\frac{1}{T}\sum_{t=1}^{T}\E\bigl[\|\nabla F(w_t)\|^2\bigr]
\le
\frac{C_v\bigl(F(w_1)-F^\star\bigr)}{\eta(1-\beta_1)^2 T}
+ \frac{L G^2 C_v}{2(1-\beta_1)^4\epsilon^2}\,\eta . \tag{21}
\]

\noindent\textbf{[Step 14]} Choose $\eta = \Theta\!\bigl(\sqrt{(F(w_1)-F^\star)/(LT)}\bigr)$ to balance the two terms. Using the explicit constants
\[
C_v = \sqrt{\frac{G^2}{1-\beta_2}}+\epsilon \le \frac{G}{\sqrt{1-\beta_2}} + \epsilon,
\]
and absorbing $\epsilon$ into $G$ for simplicity, we obtain the bound (6) stated in Theorem \ref{thm:main}:
\[
\overline{G}_T
\le
\frac{2L\bigl(F(w_1)-F^\star\bigr)}{(1-\beta_1)\eta T}
+ \frac{2\eta\,G^2\,(1+\log T)}{(1-\beta_1)(1-\beta_2)} .
\]
\hfill\qed

\section*{Rate Derivation (With Constants)}
Setting $\eta = \frac{c}{\sqrt{T}}$ for a constant $c>0$ gives
\[
\overline{G}_T
\le
\underbrace{\frac{2Lc\bigl(F(w_1)-F^\star\bigr)}{(1-\beta_1)T^{3/2}}_{\text{decays as }T^{-3/2}}
\;+\;
\underbrace{\frac{2c\,G^2\,(1+\log T)}{(1-\beta_1)(1-\beta_2)\sqrt{T}}}_{\displaystyle O\!\bigl(\tfrac{\log T}{\sqrt{T}}\bigr)} .
\]
Thus the dominant term is $O(\log T/\sqrt{T})$, establishing the claimed non‑convex convergence rate.

\section*{Special Cases}
\begin{enumerate}
\item \textbf{Convex $F$.} If $F$ is convex, the smoothness inequality (Lemma \ref{lem:smooth}) can be replaced by the standard convexity inequality, yielding an $O(\log T/T)$ bound on the optimality gap $F(\bar w_T)-F^\star$.
\item \textbf{Deterministic Gradients.} When $\sigma=0$ (i.e., $g_t=\nabla F(w_t)$), the variance term disappears and the bound simplifies to $O(1/T)$.
\item \textbf{Full‑batch Adam vs. AMSGrad.} Setting $\tilde v_t=\hat v_t$ recovers Adam; the proof then fails at Step 7 because the denominator can shrink, leading to the possible divergence illustrated in Reddi et al. (2018).
\end{enumerate}

